Object.assign(ACT,{relsel(e){RLUI.sel=e.dataset.p;RLUI.msg='';render()},relact(e){const d=relDoAct(e.dataset.p,e.dataset.k);RLUI.msg=d==null?'':t('rl.res.act',{d:(d>=0?'+':'')+Math.round(d)});save();render()},relflirt(e){const r=relFlirt(e.dataset.p);RLUI.msg=!r?'':r.ok?t(r.taken?'rl.res.taken':'rl.res.ok'):t('rl.res.no');save();render()},reldate(e){const m=meW(),c=200*relF();if(G.relAP<1||m.wallet<c)return;m.wallet-=c;G.relAP--;relAdd(e.dataset.p,6,8);RLUI.msg=t('rl.res.act',{d:'+6'});save();render()},relbreak(e){relBreak(e.dataset.p);RLUI.msg='';save();render()},lsbuyhome(){const m=lsEnsure(),nx=homeNext();if(nx==null)return;const c=Math.round(HOMES[nx][0]*(m.homeDisc?1-m.homeDisc:1));if(m.wallet<c)return;m.wallet-=c;m.home=nx;m.homeDisc=0;save();render()},lsbuycar(e){const m=lsEnsure(),i=+e.dataset.i;if(m.cars.indexOf(i)>=0||m.wallet<CARS[i][0])return;m.wallet-=CARS[i][0];m.cars.push(i);save();render()},lsinv(e){invBuy(e.dataset.k,+e.dataset.p);save();render()},lssell(e){invSellAll(e.dataset.k);save();render()},lshobby(){const m=lsEnsure();m.hobbyOff=!m.hobbyOff;save();render()},tcgbuy(e){const m=meW();if(!m)return;const k=e.dataset.k,d=TCG_PACKS[k];if(!d)return;const free=(k==='std'||k==='pre')&&m.free[k]>0,pr=tcgPrice(k);if(free)m.free[k]--;else if(m.wallet>=pr)m.wallet-=pr;else return;const cards=tcgOpen(k,m.sel);openModal(tcgModal(cards))},tcgclose(){closeModal();render()},tcgsell(){const m=meW();const d=tcgDups();if(!d.n)return;Object.values(m.col).forEach(x=>{x.n=1;x.fo=Math.min(x.fo,1)});m.wallet+=d.v;save();render()},meedit(){openModal(meEditor())},merandom(){const s=meInit();s.look=randLook(Math.random,s.country,s.g==='f');render()},meg(e){const s=meInit();s.g=e.dataset.v;s.look=randLook(Math.random,s.country,s.g==='f');render()},meclose(){closeModal();render()},merand(){const s=meInit();s.look=randLook(Math.random,s.country,s.g==='f');document.getElementById('modal').firstChild.innerHTML=meEditor()},melook(e){const s=meInit(),k=e.dataset.k;s.look[k]=(k==='skin'||k==='hairC'||k==='outC'||k==='maskC'||k==='o2'||k==='beardC')?+e.dataset.v:e.dataset.v;document.getElementById('modal').firstChild.innerHTML=meEditor()},applyjob(e){if(applyTo(e.dataset.id))render()},takejob(e){const id=e.dataset.id;closeModal();if(takeOver(id)){G.screen='dash';render()}else render()},facup(e){const k=e.dataset.k,c=facCost(k);if(!FACS.includes(k)||c<=0||G.fed.cash<c)return;G.fed.cash-=c;infra()[k]++;infra().disc=0;addNews('n.facup',{f:t('fac.'+k),l:infra()[k]});save();render()}});

