const THK='ringboss.theme.v1';
function themeGet(){try{return localStorage.getItem(THK)||''}catch(e){return ''}}
function themeApply(){const de=document.documentElement;if(!de)return;const v=themeGet();if(v)de.setAttribute('data-theme',v);else de.removeAttribute('data-theme')}
function themeIcon(){const v=themeGet();return v==='dark'?'☾':v==='light'?'☀':'◐'}
Object.assign(ACT,{theme(){const v=themeGet(),n=v===''?'dark':v==='dark'?'light':'';try{if(n)localStorage.setItem(THK,n);else localStorage.removeItem(THK)}catch(e){}themeApply();render()}});
